import React, { useEffect, useState } from 'react';
import Button from '@mui/material/Button';
import DeleteIcon from '@mui/icons-material/Delete';
import SendIcon from '@mui/icons-material/Send';
import {connect} from "react-redux"
import axios from 'axios';
import { useRef } from 'react';
import emailjs from '@emailjs/browser';
import { CircularProgress } from '@mui/material';
import {  useSnackbar } from 'notistack';

function ContactPage({data,lang}) {
    const { enqueueSnackbar } = useSnackbar();
    const link_mailto = useRef(null)
    const email = useRef(null)
    const name = useRef(null)
    const message = useRef(null)
    const subject = useRef(null)
    useEffect(() => emailjs.init("c9YofgTEwaCvcvUmq"), []);
    const [values,setValues] = useState({
        name:"",
        email:"",
        subject:"",
        message:""
    })
    const [loadding,setLoadding] = useState(false)
    const form = useRef()
    const handleChange=(e,key)=>{
        setValues(prev=>({...prev,[key]:e}))
    }
    const handleSend = ()=>{
        if(values.email.match(
            /^(([^<>()[\]\\.,;:\s@\"]+(\.[^<>()[\]\\.,;:\s@\"]+)*)|(\".+\"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/
          )){

            if(values.name.length>0 && values.subject.length>0 && values.email.length>0 && values.message.length>0){
                setLoadding(true)
                axios.get(`https://emailvalidation.abstractapi.com/v1/?api_key=856032f988d14516844070ecc3e8e4ff&email=${values.email}`)
                .then(res=>{
                    if(res.data.is_smtp_valid.value){
                        // link_mailto.current.click()
                        emailjs.sendForm('service_2bnqsyn', 'template_hv6pzfg', form.current, 'c9YofgTEwaCvcvUmq')
                            .then((result) => {
                                // show the user a success message
                                console.log(result);
                                enqueueSnackbar('Your Message has been sent successfully.',{variant:"success"});
                            }, (error) => {
                                console.log(error);
                                // show the user an error
                                enqueueSnackbar('Something is wrong,please try again.',{variant:"error"});
                            });
                            setLoadding(false)
                            
                    }else{
                        enqueueSnackbar('Please check your email if it correct .',{variant:"error"});
                        email.current.focus()
                        setLoadding(false)
                    }
                })
            }else{
                if(values.name.length == "" ){
                    name.current.focus()
                }
                if(values.subject.length == "" ){
                    subject.current.focus()
                }
                if(values.message.length == "" ){
                    message.current.focus()
                }
                enqueueSnackbar('All fields are required .',{variant:"error"});
                
            }
          }else{
            email.current.focus()
            enqueueSnackbar('Please check your email if it correct .',{variant:"error"});
          }
       
    }
    return (
        
            <div className='content contact-card p-4 '>
        <h3>
            {data.ContactPage.title}
        </h3>
        <div className='row mx-0 my-4'>
        {
            data.ContactPage.info.map((e)=>{
            
                return<div key={e.name+"hhgg"} className='col-sm-12 col-md-6 col-lg-6 my-2 d-flex justify-center '>
                    <div className='row mx-0 contact-info w-100'>
                        <div className='col-sm-12 col-md-4 col-lg-4 text-center'>
                            {e.icon}
                        </div>
                        <div className='col-sm-12 col-md-8 col-lg-8'>
                            <h5>{e.name}</h5>
                            {e.value}
                        </div>
                    </div>
               
    
            </div>
            })
        }
             
             </div>
             <form ref={form} className='form-card'>
                <div className='row mx-0 form-content'>
                    <div className='col-sm-12 col-md-6 col-lg-6  card-input1'>
                        <input ref={name} name="name" onChange={(e)=>{handleChange(e.target.value,"name")}} type="text" placeholder={lang === "EN"?'Your Name':"الأسم"} />

                    </div>
                    <div className='col-sm-12 col-md-6 col-lg-6  card-input2'>
                        <input ref={email} name="email" onChange={(e)=>{handleChange(e.target.value,"email")}}  type="email" placeholder={lang==="EN"?'Your Email':"الإيميل"} />
                    </div>

                </div>
                <div className='row mx-0 form-content'>
                    <div className='col-sm-12 col-md-12 col-lg-12 text-center card-input'>
                        <textarea ref={subject} name="subject" onChange={(e)=>{handleChange(e.target.value,"subject")}}  rows={2}  type="text" placeholder={lang==="EN"?'Subject':"الموضوع"} />

                    </div>

                </div>
                <div className='row mx-0 form-content'>
                    <div className='col-sm-12 col-md-12 col-lg-12 text-center '>
                        <textarea ref={message} name="message" onChange={(e)=>{handleChange(e.target.value,"message")}} rows={4}  type="text" placeholder={lang==="EN"?'Message':"الرسالة"} />

                    </div>
                    <div className='w-100 my-2 text-center'>
                            {
                                lang==="EN"? <Button variant="contained"  onClick={handleSend}  endIcon={loadding?"":<SendIcon />}>
                               {loadding?<CircularProgress sx={{color:"white"}} size="1.3rem"/>:"Send Message"}
                            </Button>: <Button variant="contained" onClick={handleSend}  startIcon={loadding?"":<SendIcon />}>
                           &nbsp; &nbsp; {loadding?<CircularProgress sx={{color:"white"}} size="1.3rem"/>:"ارسال"}
                        </Button>
                            }
                       
                     
                    
                </div>

                </div>
               
             </form>
             <a ref={link_mailto} href={`mailto:eng.mahaab96@gmail.com?subject='${values.subject}'&body='${values.message}'`} style={{display:"hidden"}} />
    
    

    </div>
     
    );
}
const mapStateToProps =(state)=>{
    return{
        lang: state.lang
    }
}
export default connect(mapStateToProps)(ContactPage);